changeSet.sql:
ALTER TABLE "${schema}".employee_salary_component_override
    ADD CONSTRAINT chk_emp_sal_comp_override_calc_basis
    CHECK (calculation_basis IN ('FIXED_ANNUAL','FIXED_MONTHLY','PERCENT_OF_CTC','PERCENT_OF_BASIC'));

CREATE TRIGGER trg_employee_salary_component_override_updated_at
BEFORE UPDATE ON "${schema}".employee_salary_component_override
FOR EACH ROW EXECUTE FUNCTION kabipay_ops.set_updated_at();

DO $$ DECLARE assets_module_id UUID; BEGIN SELECT permission.module_id INTO assets_module_id FROM "${schema}".permission AS permission WHERE permission.resource = 'assets' AND permission.action = 'manage' LIMIT 1;
IF assets_module_id IS NULL THEN RAISE EXCEPTION 'required base permission %.% is missing in schema ${schema}', 'assets', 'manage'; END IF;
INSERT INTO "${schema}".permission (id, resource, action, module_id, description) SELECT gen_random_uuid(), wanted.resource, wanted.action, assets_module_id, wanted.description FROM ( VALUES ('assets', 'read', 'Read tenant-wide asset inventory and employee allocations'), ('assets', 'self', 'View assets assigned to the signed-in employee') ) AS wanted(resource, action, description) WHERE NOT EXISTS ( SELECT 1 FROM "${schema}".permission AS existing_permission WHERE existing_permission.resource = wanted.resource AND existing_permission.action = wanted.action ); END $$;

CREATE UNIQUE INDEX IF NOT EXISTS uq_asset_allocation_one_active_per_asset
ON "${schema}".asset_allocation (tenant_id, asset_id)
WHERE status = 'ACTIVE';
